        // Test Scenario 1: Standard Runnable Task Execution
        System.out.println("=== Test Scenario 1: Standard Worker Execution ===");
        Runnable worker = () -> {
            System.out.println("Worker executed on thread: " + Thread.currentThread().getName());
        };
