import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class HashMapDemo {
    static class BadKey {
        final String id;
        BadKey(String id) { this.id = id; }
        @Override public int hashCode() { return 42; } // Intentional collision for demonstration
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            return Objects.equals(id, ((BadKey) o).id);
        }
    }

    public static void main(String[] args) {
        // Test Scenario 1: Standard Key Lookup
        System.out.println("=== Test Scenario 1: Standard HashMap Put and Get ===");
        Map<String, Integer> map = new HashMap<>();
        map.put("Java", 21);
        map.put("Python", 3);
        System.out.println("Java Version: " + map.get("Java"));

        // Test Scenario 2: Hash Collision Resolution with Custom Keys
        System.out.println("\n=== Test Scenario 2: Hash Collision Handling ===");
        Map<BadKey, String> collisionMap = new HashMap<>();
        BadKey k1 = new BadKey("alpha");
        BadKey k2 = new BadKey("beta");
        collisionMap.put(k1, "First Value");
        collisionMap.put(k2, "Second Value");
        System.out.println("k1 value: " + collisionMap.get(k1));
        System.out.println("k2 value: " + collisionMap.get(k2));
        System.out.println("Both keys hashed to same bucket, correctly resolved via equals()!");
    }
}

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

public class ProducerConsumerDemo {
    private static final String POISON_PILL = "STOP";

    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<String> queue = new ArrayBlockingQueue<>(5);

        // Test Scenario 1: Producer generating messages
        System.out.println("=== Test Scenario 1: Producer-Consumer Processing ===");
        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 3; i++) {
                    String task = "Task-" + i;
                    System.out.println("[Producer] Produced: " + task);
                    queue.put(task);
                    Thread.sleep(100);
                }
                queue.put(POISON_PILL);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        // Test Scenario 2: Consumer consuming until poison pill
        System.out.println("=== Test Scenario 2: Consumer Processing & Graceful Shutdown ===");
        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    String item = queue.take();
                    if (POISON_PILL.equals(item)) {
                        System.out.println("[Consumer] Received poison pill. Exiting gracefully.");
                        break;
                    }
                    System.out.println("[Consumer] Processed: " + item);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        consumer.start();
        producer.start();
        producer.join();
        consumer.join();
        System.out.println("Producer-Consumer pipeline terminated successfully.");
    }
}

public class SingletonDemo {
    public static class SafeSingleton {
        private static volatile SafeSingleton instance;
        private final long createdAt;

        private SafeSingleton() {
            this.createdAt = System.currentTimeMillis();
        }

        public static SafeSingleton getInstance() {
            if (instance == null) { // First check (no locking overhead)
                synchronized (SafeSingleton.class) {
                    if (instance == null) { // Second check (synchronized)
                        instance = new SafeSingleton();
                    }
                }
            }
            return instance;
        }

        public long getCreatedAt() { return createdAt; }
    }

    public static void main(String[] args) throws InterruptedException {
        // Test Scenario 1: Single Thread Instance Equality
        System.out.println("=== Test Scenario 1: Identity Verification ===");
        SafeSingleton s1 = SafeSingleton.getInstance();
        SafeSingleton s2 = SafeSingleton.getInstance();
        System.out.println("s1 == s2: " + (s1 == s2));

        // Test Scenario 2: Multi-Threaded Concurrent Access
        System.out.println("\n=== Test Scenario 2: Concurrent Multi-Thread Access ===");
        Runnable task = () -> {
            SafeSingleton instance = SafeSingleton.getInstance();
            System.out.println("Thread " + Thread.currentThread().getName() + " got instance: " + instance.hashCode());
        };
        Thread t1 = new Thread(task, "Thread-A");
        Thread t2 = new Thread(task, "Thread-B");
        t1.start();
        t2.start();
        t1.join();
        t2.join();
    }
}

import java.util.ArrayList;
import java.util.List;

public class GenericsPecsDemo {
    // Producer Extends: Reads numbers and computes sum
    public static double sumOfNumbers(List<? extends Number> list) {
        double sum = 0.0;
        for (Number n : list) {
            sum += n.doubleValue();
        }
        return sum;
    }

    // Consumer Super: Appends integers into destination list
    public static void appendIntegers(List<? super Integer> list, int count) {
        for (int i = 1; i <= count; i++) {
            list.add(i * 10);
        }
    }

    public static void main(String[] args) {
        // Test Scenario 1: Producer Extends with Integers and Doubles
        System.out.println("=== Test Scenario 1: sumOfNumbers with Integer & Double ===");
        List<Integer> intList = List.of(10, 20, 30);
        List<Double> doubleList = List.of(1.5, 2.5, 3.5);
        System.out.println("Sum of ints: " + sumOfNumbers(intList));
        System.out.println("Sum of doubles: " + sumOfNumbers(doubleList));

        // Test Scenario 2: Consumer Super with Number List
        System.out.println("\n=== Test Scenario 2: appendIntegers into Number List ===");
        List<Number> numList = new ArrayList<>();
        appendIntegers(numList, 3);
        System.out.println("Appended Numbers: " + numList);
    }
}

public class ExceptionDemo {
    public static class InsufficientFundsException extends Exception {
        public InsufficientFundsException(String message) { super(message); }
    }

    public static class InvalidAccountException extends RuntimeException {
        public InvalidAccountException(String message) { super(message); }
    }

    public static class BankAccount {
        private double balance;
        public BankAccount(double balance) { this.balance = balance; }

        public void withdraw(double amount) throws InsufficientFundsException {
            if (amount <= 0) throw new InvalidAccountException("Withdrawal amount must be positive.");
            if (amount > balance) throw new InsufficientFundsException("Balance $" + balance + " insufficient for $" + amount);
            balance -= amount;
            System.out.println("Withdrew $" + amount + ". Remaining: $" + balance);
        }
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount(100.0);

        // Test Scenario 1: Checked Exception Trigger
        System.out.println("=== Test Scenario 1: Catching Checked Exception ===");
        try {
            account.withdraw(150.0);
        } catch (InsufficientFundsException e) {
            System.out.println("Caught Checked Exception: " + e.getMessage());
        }

        // Test Scenario 2: Unchecked Exception Trigger
        System.out.println("\n=== Test Scenario 2: Catching Unchecked Runtime Exception ===");
        try {
            account.withdraw(-20.0);
        } catch (InvalidAccountException e) {
            System.out.println("Caught Unchecked Exception: " + e.getMessage());
        } catch (InsufficientFundsException e) {
            System.out.println("Unexpected: " + e.getMessage());
        }
    }
}

import java.util.concurrent.atomic.AtomicInteger;

public class LockFreeCounterDemo {
    static class LockFreeCounter {
        private final AtomicInteger count = new AtomicInteger(0);

        public void increment() {
            count.incrementAndGet();
        }

        public int getValue() {
            return count.get();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        LockFreeCounter counter = new LockFreeCounter();

        // Test Scenario 1: Multi-threaded concurrent increments
        System.out.println("=== Test Scenario 1: Concurrent High-Contention Increments ===");
        int threadCount = 4;
        int incrementsPerThread = 2500;
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            threads[i] = new Thread(() -> {
                for (int j = 0; j < incrementsPerThread; j++) {
                    counter.increment();
                }
            });
            threads[i].start();
        }

        for (Thread t : threads) {
            t.join();
        }
        System.out.println("Expected: " + (threadCount * incrementsPerThread) + ", Actual: " + counter.getValue());

        // Test Scenario 2: Atomic CAS update validation
        System.out.println("\n=== Test Scenario 2: CAS Validation ===");
        AtomicInteger atomic = new AtomicInteger(100);
        boolean success = atomic.compareAndSet(100, 200);
        boolean failed = atomic.compareAndSet(100, 300);
        System.out.println("CAS (100 -> 200) Success: " + success + ", Current: " + atomic.get());
        System.out.println("CAS (100 -> 300) Success: " + failed + ", Current: " + atomic.get());
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

public class CompletableFutureDemo {
    public static void main(String[] args) throws ExecutionException, InterruptedException {
        // Test Scenario 1: Parallel Fan-Out and Aggregation
        System.out.println("=== Test Scenario 1: Parallel Fetch & Combine ===");
        CompletableFuture<String> userFuture = CompletableFuture.supplyAsync(() -> {
            return "UserData[Alice]";
        });
        CompletableFuture<String> orderFuture = CompletableFuture.supplyAsync(() -> {
            return "OrderData[Item#42]";
        });

        CompletableFuture<String> aggregated = userFuture.thenCombine(orderFuture, (user, order) -> user + " + " + order);
        System.out.println("Aggregated Result: " + aggregated.get());

        // Test Scenario 2: Exceptional Handling Fallback
        System.out.println("\n=== Test Scenario 2: Error Recovery via exceptionally() ===");
        CompletableFuture<String> failingTask = CompletableFuture.supplyAsync(() -> {
            if (true) throw new RuntimeException("Remote service timeout!");
            return "Success";
        }).exceptionally(ex -> {
            System.out.println("Logged error: " + ex.getMessage());
            return "FallbackCachedData";
        });
        System.out.println("Recovered Result: " + failingTask.get());
    }
}

