public class PatternMatchingDemo {
    public static String formatValue(Object obj) {
        return switch (obj) {
            case Integer i -> String.format("Integer: %d (square: %d)", i, i * i);
            case String s when s.isBlank() -> "Blank String";
            case String s -> String.format("String length: %d ('%s')", s.length(), s);
            case Double d -> String.format("Double: %.2f", d);
            case null -> "Null object provided";
            default -> "Unknown type: " + obj.getClass().getSimpleName();
        };
    }

    public static void main(String[] args) {
        // Test Scenario 1: Matching Diverse Types
        System.out.println("=== Test Scenario 1: Diverse Type Formatting ===");
        System.out.println(formatValue(12));
        System.out.println(formatValue("Hello Pattern Matching"));
        System.out.println(formatValue(99.954));

        // Test Scenario 2: Edge Cases (Blank string and null)
        System.out.println("\n=== Test Scenario 2: Null and Blank Edge Cases ===");
        System.out.println(formatValue("   "));
        System.out.println(formatValue(null));
    }
}

