import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;

public class DeadlockPreventionDemo {
    private static final ReentrantLock lockA = new ReentrantLock();
    private static final ReentrantLock lockB = new ReentrantLock();

    public static void safeOperation() {
        boolean acquiredA = false;
        boolean acquiredB = false;
        try {
            acquiredA = lockA.tryLock(500, TimeUnit.MILLISECONDS);
            acquiredB = lockB.tryLock(500, TimeUnit.MILLISECONDS);
            if (acquiredA && acquiredB) {
                System.out.println(Thread.currentThread().getName() + " acquired both locks safely!");
            } else {
                System.out.println(Thread.currentThread().getName() + " backed off to prevent deadlock.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            if (acquiredB) lockB.unlock();
            if (acquiredA) lockA.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        // Test Scenario 1: Normal Thread Execution
        System.out.println("=== Test Scenario 1: Safe Lock Acquisition ===");
        Thread t1 = new Thread(DeadlockPreventionDemo::safeOperation, "Worker-1");
        t1.start();
        t1.join();

        // Test Scenario 2: Concurrent Contention without Deadlock
        System.out.println("\n=== Test Scenario 2: Concurrent Threads with Timeout Backoff ===");
        Thread t2 = new Thread(DeadlockPreventionDemo::safeOperation, "Worker-2");
        Thread t3 = new Thread(DeadlockPreventionDemo::safeOperation, "Worker-3");
        t2.start();
        t3.start();
        t2.join();
        t3.join();
        System.out.println("Completed without circular wait or deadlock!");
    }
}

