public class CloningDemo {
    static class Address {
        String city;
        Address(String city) { this.city = city; }
        Address(Address other) { this.city = other.city; } // Deep copy constructor
    }

    static class User {
        String name;
        Address address;
        User(String name, Address address) { this.name = name; this.address = address; }
        // Deep copy constructor
        User(User other) {
            this.name = other.name;
            this.address = new Address(other.address);
        }
    }

    public static void main(String[] args) {
        Address addr = new Address("New York");
        User original = new User("Alice", addr);

        // Test Scenario 1: Deep Copy Isolation
        System.out.println("=== Test Scenario 1: Deep Copy Isolation ===");
        User cloned = new User(original);
        cloned.address.city = "San Francisco";
        System.out.println("Original City: " + original.address.city);
        System.out.println("Cloned City:   " + cloned.address.city);

        // Test Scenario 2: Reference Identity Check
        System.out.println("\n=== Test Scenario 2: Reference Inequality Verification ===");
        System.out.println("original == cloned: " + (original == cloned));
        System.out.println("original.address == cloned.address: " + (original.address == cloned.address));
    }
}

import java.util.concurrent.*;

public class ThreadPoolTuningDemo {
    public static void main(String[] args) throws InterruptedException {
        int corePool = 2;
        int maxPool = 4;
        long keepAlive = 10L;
        BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(2);

        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            corePool,
            maxPool,
            keepAlive,
            TimeUnit.SECONDS,
            queue,
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        // Test Scenario 1: Submitting tasks within capacity
        System.out.println("=== Test Scenario 1: Submitting Standard Tasks ===");
        for (int i = 1; i <= 3; i++) {
            final int id = i;
            executor.submit(() -> {
                System.out.println("Task " + id + " running on " + Thread.currentThread().getName());
            });
        }

        // Test Scenario 2: Handling Burst Submissions with CallerRunsPolicy
        System.out.println("\n=== Test Scenario 2: Burst Submissions Triggering Backpressure ===");
        for (int i = 4; i <= 8; i++) {
            final int id = i;
            executor.submit(() -> {
                System.out.println("Burst Task " + id + " running on " + Thread.currentThread().getName());
            });
        }

        executor.shutdown();
        executor.awaitTermination(2, TimeUnit.SECONDS);
        System.out.println("\nExecutor terminated cleanly.");
    }
}
